{"command": "cd /tmp && curl -s -m 15 -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" https://www.chinanews.com.cn/ -o cn.html && python3 - <<'EOF'
import re,html
t=open('/tmp/cn.html',encoding='utf-8',errors='ignore').read()
links=re.findall(r'<a[^>]*href="(https?://[^"]*chinanews[^"]*)"[^>]*>(.*?)</a>',t,re.S)
seen=set();out=[]
for u,txt in links:
    s=html.unescape(re.sub('<[^>]+>','',txt)).strip()
    if len(s)>=8 and s not in seen:
        seen.add(s);out.append(s)
print(len(out))
for s in out[:40]:print('-',s)
EOF", "yieldMs": 30000}
